            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x3CC869565DE962EAULL) + aOrbiterUpdateSaltD[((aIndex + 22U)) & S_SALT1];
            aOrbiterH = (((aOrbiterH ^ aOrbiterF) ^ 0x42F3156A85A486C0ULL) ^ aOrbiterUpdateSaltC[((aIndex + 24U)) & S_SALT1]) ^ aNonceWordI;
