        //
        // Ingress:
        //      aWaterLaneA (-->), aWindLaneC (-->), aSource (-->), aPoisonLaneC (<-?->)
        //
        // Cross:
        //      aWindLaneA (<--), aWindLaneD (<--), aFireLaneD (<--), aFireLaneA (<-?->)
        //
        // Destination:
        //      aWaterLaneB
