            aPrevious = aIngress;
            //
            aIngress = (RotL64(aFireLaneA[((aIndex + 668U)) & S_BLOCK1], 3U) ^ RotL64(aFireLaneB[((aIndex + 4169U)) & S_BLOCK1], 35U));
