            aScatter = (RotL64(aCarry, 3U) ^ RotL64(aPrevious, 40U)) ^ (RotL64(aIngress, 23U) + RotL64(aCross, 53U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterC = ((aWandererF + RotL64(aIngress, 11U)) + RotL64(aCarry, 27U)) + 0x63D9C937F150B5D1ULL;
            aOrbiterD = ((aWandererB + RotL64(aPrevious, 53U)) + 0x3483A3677D174D6EULL) + aPhaseBOrbiterAssignSaltD[(((31U - aIndex) + 5U)) & S_SALT1];
