            aOrbiterB = ((aWandererC + RotL64(aScatter, 29U)) + RotL64(aCarry, 11U)) + 0x0E1625AFAB4248D2ULL;
            aOrbiterJ = (aWandererJ + RotL64(aIngress, 35U)) + 0xAE1E5BE0DA2FD817ULL;
            aOrbiterI = (((aWandererG + RotL64(aCross, 44U)) + RotL64(aCarry, 47U)) + 0x9C26FC56BE289174ULL) + aPhaseBOrbiterAssignSaltA[((aIndex + 10U)) & S_SALT1];
            aOrbiterG = (aWandererI + RotL64(aScatter, 5U)) + 0xEB6A20E888DE9722ULL;
            //
            aOrbiterC = ((aOrbiterC + aOrbiterD) + 0xDB06EF109E6B7A25ULL) + aPhaseBOrbiterUpdateSaltF[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterC) ^ 0x4427B7EC8D5282B8ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x3C527172E90CDC65ULL), 35U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0xED0A9909E2CE9E94ULL) + aPhaseBOrbiterUpdateSaltE[((aIndex + 7U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0xEDAD1947B11B6F19ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xADA9F128D147B52BULL), 19U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0x8E5DE99648A37C7CULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x57C31B66FEB9FDB4ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xC1C8B3F3C3A27EAFULL), 5U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterI) + 0xB0447B8FCE32D61FULL) + aPhaseBOrbiterUpdateSaltB[((aIndex + 13U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0xBF15D951F44334FEULL;
            aOrbiterD = RotL64((aOrbiterD * 0xA889299384D47B49ULL), 27U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0xD29EB183B8E1D792ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterF) ^ 0xF0CEDA91217518BDULL) ^ aPhaseBOrbiterUpdateSaltD[(((31U - aIndex) + 29U)) & S_SALT1];
