            aWandererA = aWandererA + (((RotL64(aPrevious, 23U) + RotL64(aOrbiterF, 51U)) + aOrbiterJ) + aPhaseBWandererUpdateSaltE[(((31U - aIndex) + 19U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aIngress, 12U) + RotL64(aOrbiterI, 27U)) + aOrbiterF);
