            aOrbiterC = (aWandererF + RotL64(aIngress, 35U)) + 0x8AD8BECFBC96C6D3ULL;
            aOrbiterI = ((aWandererC + RotL64(aPrevious, 29U)) + RotL64(aCarry, 47U)) + 0x0CD59AE399D86E41ULL;
            aOrbiterE = ((aWandererG + RotL64(aScatter, 41U)) + 0xD4FD9A8E349AE69EULL) + aPhaseCOrbiterAssignSaltC[((aIndex + 23U)) & S_SALT1];
            aOrbiterK = (((aWandererK + RotL64(aCross, 13U)) + RotL64(aCarry, 13U)) + 0x40903167B06212C7ULL) + aPhaseCOrbiterAssignSaltF[((aIndex + 16U)) & S_SALT1];
            aOrbiterF = (aWandererE + RotL64(aPrevious, 21U)) + 0xA315CF98E239F3A8ULL;
            aOrbiterG = (aWandererA + RotL64(aCross, 47U)) + 0x3A3437C5E125359EULL;
            aOrbiterD = ((aWandererH + RotL64(aIngress, 6U)) + RotL64(aCarry, 35U)) + 0xC92C11BEF6516757ULL;
            //
            aOrbiterC = (aOrbiterC + aOrbiterI) + 0xE1D715743C325E7CULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterC) ^ 0xBDA8AFEDCB34B3BFULL) ^ aPhaseCOrbiterUpdateSaltE[((aIndex + 3U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xEBAD22F0DCB55343ULL), 41U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x05950F50B63C1F27ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x8D591A3858212BE2ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x4B76B25881E1D9D9ULL), 29U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x1CA49A69E22F47A8ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0xC82A9D71CDF966AFULL;
