            //
            aOrbiterI = ((aOrbiterI + aOrbiterD) + 0xA07E3E3CEC62CFCCULL) + aPhaseCOrbiterUpdateSaltF[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0xA5F0F1A0BAFAD46EULL;
            aOrbiterG = RotL64((aOrbiterG * 0xCA0C04BA723E13D3ULL), 57U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0xD4C765354FE76940ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0xE9C5D8FDBC80F709ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x7498C33886A4ECA1ULL), 19U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterK) + 0xE0A5D51B0660F13AULL) + aPhaseCOrbiterUpdateSaltD[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x65FD44B57956241BULL;
            aOrbiterC = RotL64((aOrbiterC * 0x5E4240E195363D19ULL), 5U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x399591C62485A637ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterG) ^ 0x6087673988E86651ULL) ^ aPhaseCOrbiterUpdateSaltB[((aIndex + 8U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x3996E39C27B29ED3ULL), 11U);
            //
            aIngress = RotL64(aOrbiterI, 42U) ^ aOrbiterC;
            aIngress = aIngress + (RotL64(aOrbiterF, 11U) ^ aOrbiterE);
            aIngress = aIngress + (RotL64(aOrbiterK, 19U) ^ aOrbiterG);
            aIngress = aIngress + RotL64(aOrbiterD, 57U);
