            aWandererK = aWandererK ^ ((RotL64(aPrevious, 3U) + RotL64(aOrbiterK, 47U)) + aOrbiterF);
            aWandererE = aWandererE + ((((RotL64(aCross, 27U) + aOrbiterK) + RotL64(aOrbiterD, 60U)) + RotL64(aCarry, 5U)) + aPhaseCWandererUpdateSaltE[((aIndex + 6U)) & S_SALT1]);
