            aWandererH = aWandererH + (((RotL64(aScatter, 47U) + aOrbiterI) + RotL64(aOrbiterE, 39U)) + RotL64(aCarry, 37U));
            aWandererF = aWandererF ^ ((RotL64(aCross, 19U) + RotL64(aOrbiterC, 19U)) + aOrbiterE);
            aWandererG = aWandererG + ((RotL64(aIngress, 53U) + aOrbiterK) + RotL64(aOrbiterE, 53U));
            aWandererC = aWandererC ^ (((RotL64(aPrevious, 12U) + RotL64(aOrbiterC, 13U)) + aOrbiterI) + aPhaseCWandererUpdateSaltD[(((31U - aIndex) + 26U)) & S_SALT1]);
