            aOrbiterA = (aWandererC + RotL64(aScatter, 23U)) + 0x0A4EC2E28475057EULL;
            aOrbiterE = ((aWandererF + RotL64(aIngress, 3U)) + RotL64(aCarry, 13U)) + 0x12351E74BE6090A1ULL;
            aOrbiterD = (aWandererB + RotL64(aCross, 11U)) + 0x15A6F87C590B52AEULL;
            aOrbiterK = (aWandererE + RotL64(aPrevious, 19U)) + 0xC9298A703125C60CULL;
